insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'l1', 5, 'list', 'event', $t$1983: Barpeta, Sonitpur, Jorhat, Dhubri, Kokrajhar and Karimganj districts are created.
1989: Hailakandi, Bongaigaon, Tinsukia, Dhemaji and Morigaon are created.
2003 to 2004: Kamrup Metropolitan, Baksa, Chirang and Udalguri are created.
15 August 2015: five new districts are announced (Biswanath, Charaideo, Hojai, South Salmara-Mankachar and West Karbi Anglong).
2016: Majuli becomes India's first {{term:river-island|river island}} district.
2020 to 2022: Bajali (34th) and Tamulpur (35th) become districts.
31 December 2022: four new districts are merged back temporarily; in August 2023 the government decides to recreate them, and the number returns to 35.$t$, null from public.content where slug = $t$districts-of-assam-overview$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p3', 6, 'paragraph', 'normal', $t$Karimganj district has been renamed Sribhumi. Assam has also set up {{term:co-district|co-districts}} to bring offices closer to people; these are not separate districts.$t$, null from public.content where slug = $t$districts-of-assam-overview$t$ on conflict do nothing;
