insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$অসমত ৩৫ খন {{term:district|জিলা}} আছে। প্ৰতিখন জিলাৰ মুৰব্বী এগৰাকী {{term:deputy-commissioner|উপায়ুক্ত}} আৰু প্ৰতিখন জিলা কেইটামান {{term:sub-division|মহকুমাত}} বিভক্ত।$t$, null from public.content where slug = $t$districts-of-assam-overview$t$ on conflict do nothing;
